INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Ghana ARC 2019 50%', 'https://www.kokkensvinhus.dk/shop/sbs-ghana-arc-2019-50/', 999.95, TRUE, NULL, 50, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/10/Product-billede-4.png', 'SBS Ghana ARC 2019 50% – Single Cask Rom SBS Ghana ARC 2019 50% er en spændende rom fra Ghana, udvalgt af SBS – Single Barrel Selection. Rommen er destilleret i 2019 og tappet ved en alkoholstyrke på 50 %. Aftapningen henvender sig til romentusiaster, der ønsker at udforske rom fra Vestafrika og opleve nye nuancer inden for romverdenen. SBS Ghana ARC 2019 er et interessant valg for både samlere og kendere, der søger anderledes rom med tydelig geografisk oprindelse.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Mauritius 2009 46% – Single Cask Rom', 'https://www.kokkensvinhus.dk/shop/sbs-mauritius-2009-46-single-cask-rom/', 849.95, TRUE, NULL, 46, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/10/Product-billede-4.png', 'et specifikt fad og giver mulighed for at opleve den særlige karakter,', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('24 Days of Rum Calendar, SBS Edition', 'https://www.kokkensvinhus.dk/shop/24-days-of-rum-calendar-sbs-edition/', 999.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/09/Product-billede-3-1.png', 'ÅRETS VILDESTE ROM SAMLING! M.FINE BESKRIVELSER.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Penultimus 15 yo, Exceptional Cask Selection – Mark XXX, 57% (bottled 2025)', 'https://www.kokkensvinhus.dk/shop/foursquare-penultimus-15-yo-exceptional-cask-selection-mark-xxx-57-bottled-2025/', 1099.95, TRUE, NULL, 57, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/09/Foursquare-Penultimus-.png', 'Som den næstsidste udgivelse i Exceptional Cask Selection-serien er Penultimus en historisk og uundværlig flaske for enhver seriøs romsamler.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Patridom XO Cognac Finish 43 %', 'https://www.kokkensvinhus.dk/shop/patridom-xo-cognac-finish-43/', 599.95, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/09/PAT-XO-COG.png', 'Patridom XO Cognac Finish Dette er en eksklusiv XO-rom fra Den Dominikanske Republik, hvor klassisk dominikansk romtradition møder fransk cognac. Rommen har gennemgået en ekstra lagring på tidligere anvendte cognacfade, som tilfører ekstra kompleksitet, dybde og elegante fadnuancer. I glasset møder du en harmonisk kombination af moden tropisk frugt, vanilje, karamel og tørrede frugter, suppleret af fine krydderier og afrundede trænoter. Smagen er fyldig og silkeblød med en lang, varm og elegant afslutning.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Old St. Croix XO Tribute Reserve 42 %', 'https://www.kokkensvinhus.dk/shop/old-st-croix-xo-tribute-reserve/', 639.95, TRUE, NULL, 42, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/08/Tribute-reserve-AH-Riise.png', 'A.H. Riise har været til numerolog Her sidste nyt Old St. Croix XO Tribute Reserve.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Tepuy Destino 40 %, Venezuela', 'https://www.kokkensvinhus.dk/shop/ron-tepuy-destino-venezuelansk-premium-rom/', 329.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/08/Tepuy-Destino-rom.png', 'Gold ved London Spirits Competition 2026.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Tepuy MONUMENTO 40%, Venezuela', 'https://www.kokkensvinhus.dk/shop/ron-tepuy-monumento-40-venezuela/', 449.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/08/Tepuy-Monumento-Rom.png', 'Ron Tepuy Momento – Venezuelansk Premium Rom Ron Tepuy Momento er en elegant venezuelansk premium rom fra DUSA, skabt med inspiration fra de majestætiske tepuy-bjerge i Venezuelas Gran Sabana. Rommen kombinerer traditionel venezuelansk romproduktion med en moderne og raffineret tilgang til fadlagring. I glasset fremstår Ron Tepuy Momento med en indbydende gylden til ravfarvet nuance. Duften byder på sødmefulde noter af vanilje, karamel og tørret frugt med fine krydrede og træagtige undertoner. Smagen er rund og harmonisk med nuancer af moden frugt, karamel, vanilje, egetræ og varme krydderier. Den velafbalancerede struktur giver en blød og behagelig afslutning. Ron Tepuy Momento er udviklet til at kunne nydes rent og er samtidig velegnet som base i elegante romcocktails. Den henvender sig til romelskere, der søger en blød, kompleks og karakterfuld venezuelansk rom med tydeligt fokus på fadlagring og balance. Ron Tepuy Momento er et spændende valg for dig, der ønsker at udforske premium rom fra Venezuela og moderne sydamerikansk romkunst.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo Blanco rum 40%. 1 l.', 'https://www.kokkensvinhus.dk/shop/abuelo-blanco-rum-40/', 299.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/02/Abuelo-White-Rum-1l-e1774692481564.jpg', 'Abuelo Blanco Rum 40% er en frisk og let hvid rom med subtile noter af vanilje og citrus, perfekt til cocktails. Bemærk 1.liter', '2026-11-08 11:00:00+01');
