INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Convocation 14 års Single Blended Rum 62%, Barbados', 'https://www.kokkensvinhus.dk/shop/foursquare-convocation-14-aars-single-blended-rum-62-barbados/', 1199, TRUE, NULL, 62, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/02/Foursquare-Convocation-14-YO.jpg', 'En eftertragtet Barbados‑rom for samlere og entusiaster', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Navy Islands Sauternes Finish,46 %', 'https://www.kokkensvinhus.dk/shop/navy-islands-sauternes-finish46/', 529.95, TRUE, NULL, 46, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/06/Navy-Island-Sauternes.png', 'Fyldig jamaicansk rom med noter af tropisk frugt, honning, vanilje og krydderier, afrundet af en elegant finish fra franske Sauternes-vinfade.', '2026-11-08 11:00:00+01');
