INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Smith &amp; Cross Traditional Jamaica Rum -57%', 'https://www.kokkensvinhus.dk/shop/smith-cross-traditional-jamaica-rum-57/', 379, TRUE, NULL, 57, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/02/Smith-Cross-Traditional-Jamaica-Rum.jpg', 'En intens og autentisk jamaicansk rom med karakteristisk “funk” og kraftfuld aroma til seriøse entusiaster.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Thailand 5 yo Rum 43% Cane Island', 'https://www.kokkensvinhus.dk/shop/thailand-5-yo-rum-43-cane-island/', 449, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/02/Thailand-cane-island.png', 'Cane Island Thailand Cane Island Thailand Rum 5 år er en velafbalanceret og kompleks rom, der er lagret i amerikanske egetræsfade, hvilket giver den en blød og fyldig karakter. Destilleret i Pathum Thani-provinsen, Thailand, på en kolonne-still, denne single estate-rom byder på en dyb amberfarve og en intens smag af vanilje, karamel og lette krydderier. Den 43 % alkoholvolumen sikrer en kraftfuld og smidig finish, perfekt til både klassiske cocktails eller som nyderne alene. Denne rom er ideel til dem, der søger noget unikt fra Thailand med en sofistikeret og let krydret profil. For en perfekt oplevelse, servér den over is eller i en mørk og stormfuld cocktail.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Voyage 9YO Collectors release Singlecask Port 42,7%', 'https://www.kokkensvinhus.dk/shop/voyage-9yo-collectors-release-singlecask-port-427/', 599, TRUE, NULL, 42.7, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/02/vouage-9-yo-port-finish.jpg', 'En sjælden og kompleks rom, lagret i portvinsfade for en intens og fyldig smagsoplevelse.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('24 x Magiske Rom - julekalender', 'https://www.kokkensvinhus.dk/shop/24-x-magiske-rom-julekalender/', 549.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/24-x-magics-rom-2025.jpg', 'Til dig selv eller én, der fortjener lidt ekstra forkælelse i december. 24 x Magiske Rom', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cristobal Santa Maria  Calvados Finish 42%', 'https://www.kokkensvinhus.dk/shop/cristobal-santa-maria-calvados-finish-42/', 599.95, TRUE, NULL, 42, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/Cristobal-Santa-Maria-Calvados-Finish-42.jpg', 'Christobal - Rom med calvados-fadfinishRon Cristóbal Santa Maria Calvados Cask Finish er en eksklusiv rom fra Den Dominikanske Republik, destilleret i 2010 og efterlagret på fade, der tidligere har indeholdt calvados. Serien er limiteret: kun ca. 2.192 flasker af denne udgave. I næsen oplever du Friske grønne æble- og pærenoter kombineret med karamel og blød vanilje. Smagen er en sprød frugtighed af æble og pære, balanceret med varme krydderier; eftersmagen er lang, med cremet vanilje og rig karamel. Fadfinish på calvadosfade giver vinen/romen en unik karakter – frugtagtig friskhed møder elegant sødme og varme. Begrænset oplag gør den til en potentiel samler- eller gaveflaske. Velegnet både til ren nydelse (med eller uden is) og til at imponere ved særlige lejligheder.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dictador Altisimo Rum The best of 1987, 43%', 'https://www.kokkensvinhus.dk/shop/dictador-altisimo-rum-the-best-of-1987-43/', 3499, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/06/Dictador-1987.jpg', 'Dictador Altisimo Rum The best of 1987 ''Best Of''-serien fra Dictador indeholder et udvalg af de bedste og ældste fade fra Destileria Colombiana. Fadene, som er omhyggeligt udvalgt af Master Parra, er amerikansk egetræs-, sherry- eller portvinsfade. Alle etiketter er håndskrevne og signeret af Master Blender Hernan Parra. ALTISIMO-udgaven af ​​Best Of-serien bruger unikke whiskyfade fra det skotske højland. Ideen bag den er at skabe en kombination af blomsteraromaer, tørv og røg. Begrænset til 300 flasker på verdensplan. Bagsiden af ​​Dictador BEST OF-serien kan indeholde tilføjelsen "Spirit Drink". Dette er en tilføjelse, der blev påkrævet i 2016 af toldmæssige årsager for salg i Colombia, hvor Destileria Colombiana ligger. Alle Dictador BEST OF''er er 100% ren rom. "Alle vores rom er rom. I 2016 havde vi et problem med de colombianske myndigheder, og der var et lille parti Best of''er, hvor vi måtte skrive "Spirit Drink" på bagsiden. Det var kun tilfældigt. Jeg håber, det ikke bliver et stort problem for dig." - Dictador Tidligere bestilte producenten Dictador forskellige virksomheder til at producere glasflaskerne. På grund af de forskellige glastykkelser kan en direkte sammenligning have den optiske effekt, at nogle aftapninger indeholder for lidt fyldningsvolumen. Dette er ikke tilfældet, alle flasker har det angivne indhold. "Som oplyst af produktionsteamet brugte vi tidligere en anden glasleverandør, og flasken havde en meget tyndere bund, deraf denne visuelle effekt i nogle af vores flasker. Du er velkommen til at åbne en flaske på vores regning og tjekke den." - Dictador Smagsnoter: Farve: Rav. Næse: Frugtagtig, honning, noter af træ, krydderier. Smag: Blød, sød, noter af tropisk frugt, krydderier. Eftersmage: Langvarig, krydret.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dictador Rum The best of 1978, 41,%', 'https://www.kokkensvinhus.dk/shop/dictador-rum-the-best-of-1978-41/', 3799, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/06/Dictador-1978.jpg', 'Dictador BEST OF 1978 EXTREMO Colombian Rum Limited Release Dette er en sand sjældenhed og en af ​​de mest eksklusive rom fra Colombia. Med en imponerende modningsperiode på 41 år modnes denne rom på fad EX-SM218, hvilket giver den enestående dybde og kompleksitet. De 41 års modning under de perfekte klimatiske forhold i Colombia gør denne rom til et sandt mesterværk inden for romkunst. Den begrænsede aftapning på kun 300 flasker på verdensplan understreger denne roms eksklusivitet og gør den til et eftertragtet samlerobjekt for kendere og elskere af sjældne spiritus. Dictador BEST OF 1978 EXTREMO er kendetegnet ved sin rige, fyldige smag, der kombinerer aromaer af karamel, mørke frugter og en fin eg- og krydderinote. Hver flaske fortæller historien om årtiers modning, der har resulteret i en afbalanceret, men kraftfuld rom. Med en fadstyrke, der er bevaret i denne udgave, tilbyder denne rom ægte intensitet og exceptionelle smagsoplevelser for sande romelskere. Smagsnoter: Farve: Mørk mahogni med dybe gyldne refleksioner. Næse: Moden tropisk frugt, karamel, vanilje, chokolade, eg, tobak, subtile krydderier. Smag: Fyldig og kompleks, aromaer af mørke frugter, honning, karamel, mørk chokolade, krydret eg, lidt læder og subtil røgelse. Eftersmage: Lang og varm, med en kombination af søde karamelnoter, eg og et elegant strejf af krydderi. Dictador BEST OF 1978 EXTREMO er perfekt at nyde ren eller på is for fuldt ud at opleve de ekstraordinære smagsnuancer. Den er et fremragende akkompagnement til mørk chokolade, moden ost som Gouda eller Parmesan, samt grillet kød eller fine cigarer. På grund af sin eksklusive natur er denne rom også et perfekt valg til en fin Rom Old Fashioned eller en Rum Manhattan, hvor de intense aromaer kommer til sin ret.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Don Omario Belize Rum', 'https://www.kokkensvinhus.dk/shop/don-omario-belize-rum/', 849, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/don-omario-Belize.jpg', 'Don Omario Belize Rum er en anerkendt premium lagret rom fra Travellers Distillery i Belize, opkaldt efter destilleriets grundlægger Jaime Omario Perdomo Sr.. Rommen er kendt for sin fyldige smagsprofil . Denne rom er først lanceret for at ære arven efter grundlæggeren Don Omario på 10-årsdagen for hans død. Denne vintage-udgave er en sand perle af rom med en fremragende blanding, håndlavet og lagret første gang af Master Blender selv - Don Omario Perdomo. Denne rom har smage af en jordagtig baggrund, kaffe, chokolade, kødfulde, ikke-sure frugter - svesker, tørrede abrikoser og dadler. I 1953 åbnede en ung mand fra Belize (dengang Britisk Honduras) ved navn Jaime Omario Perdomo sammen med sin støttende kone, Perla, en bar kaldet "Travellers". Navnet kom fra dens succes med at betjene rejsende kunder langs hovedruten ind og ud af Belize City. På det tidspunkt var det sædvanligt, at hver bar blandede sin egen rom til videresalg. Don Omario skabte sine blandinger, som hurtigt blev populære, da han mærkede og brandede rom, vin, vodka og eksotiske likører ved hjælp af lokale beliziske frugter. Travellers Liquors Ltd. blomstrede under ledelse og inspiration af vores grundlægger. Efterhånden som konkurrencen fra andre destillerier voksede, forbedrede Travellers konsistensen inden for blandingerne, hvilket førte til skabelsen af ​​den prisvindende 1 Barrel Refined Old Rum og 25 andre fine produkter. Traditionen lever videre gennem hans børn og børnebørn, der nu leder virksomheden.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Espero Caribbean Coconut &amp; Rum, 40% .', 'https://www.kokkensvinhus.dk/shop/espero-caribbean-coconut-rum-40/', 329, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/05/Espero-Coconut-Rum.jpg', 'Espero Caribbean Coconut &amp; Rum Dette er en lækker og eksotisk romlikør, der kombinerer blød dominikansk rom med naturlig kokosnød. Resultatet er en rund og cremet smagsoplevelse med søde, tropiske noter og en let, blød finish. Perfekt som ingrediens i cocktails, over is eller blot nydt rent for en smag af Caribien i hvert glas.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Espero Carribean Coffee &amp; Rum', 'https://www.kokkensvinhus.dk/shop/espero-carribean-coffee-rum/', 329, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/06/Espero-Coffe-Rum.jpg', 'Ron Espero Coffee &amp; Rum – Smagfuld kafferom med dybde og sødme Ron Espero Coffee &amp; Rum er en sød og aromatisk kafferom, der forener fyldig rom med intens kaffesmag i perfekt harmoni. Denne romlikør er skabt til dig, der elsker blød rom med karakter og en rund, cremet finish. Basen er Ron Espero Reserva Especial, som er blended rom fra Den Dominikanske Republik, lagret op til 12 år efter solera-metoden. Til dette tilføjes naturlig kaffeinfusion, hvilket skaber en rig, mørk og silkeblød coffee rum, ideel som dessertrom eller i cocktails. Smagen byder på noter af ristet kaffe, mørk chokolade, karamel, vanilje og en smule krydret romvarme. Eftersmagen er blød, sød og vedvarende – perfekt til at nyde ren, over is eller som et raffineret twist i en Espresso Martini. Med sin velbalancerede sødme og tydelige kaffenoter er Ron Espero Coffee &amp; Rum populær blandt både romelskere og kaffeentusiaster. Den elegante flaske gør den også til en oplagt gaveidé. Opdag en premium kafferom, der kombinerer latinamerikansk romtradition med ægte kaffeglæde – Ron Espero Coffee &amp; Rum er en uundværlig del af enhver velassorteret hjemmebar.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Gosling Family Reserve Bermuda', 'https://www.kokkensvinhus.dk/shop/gosling-family-reserve-bermuda/', 699, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/01/Gosling-Reserve.jpg', 'I stedet for at fokusere på alder fremhæver Gosling’s Family Reserve kvaliteten af blendet og dette håndværk.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Gosling''s Black Seal sampak', 'https://www.kokkensvinhus.dk/shop/goslings-black-seal-sampak/', 349, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/01/gosling-kit.jpg', 'Denne Dark ’n Stormy-æske fra Gosling’s indeholder en flaske klassisk Gosling’s Black Seal Rum samt fire dåser Gosling’s Stormy Ginger Beer – alt, hvad du behøver for at mixe den ikoniske Dark ’n Stormy cocktail derhjemme. Rummen i gaveæsken er omhyggeligt sammensat og nænsomt lagret i små partier, hvilket sikrer en fyldig, afrundet smag og en høj kvalitet. Sådan laver du en Dark ’n Stormy med sættet: Fyld et glas med isterninger og hæld Gosling’s Stormy Ginger Beer over, indtil glasset næsten er fyldt. Top forsigtigt med 5 cl Gosling’s Black Seal Rum, så den karakteristiske lagdeling opstår. Pynt eventuelt med en limebåd for ekstra friskhed.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('IPS 2 Barbados Rum 2025 52% Infernal Personal Selection', 'https://www.kokkensvinhus.dk/shop/infernal-2-edt-ips-limited-12-yo-babados-rom-52/', 1099, TRUE, NULL, 52, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/infernal-IPS-2-signature.jpg', 'Denne limited edition-rom er signeret af Line &amp; Paw', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk &amp; Sweeney Rum - Gran Reserva', 'https://www.kokkensvinhus.dk/shop/kirk-sweeney-rum-gran-reserva/', 399.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/07/Kirk-Sweeney-Gran-Reserve.jpg', 'Kirk &amp; Sweeney Gran Reserva – Dominikansk luksusrom Kirk &amp; Sweeney Gran Reserva ( ca 18 år ) er en eksklusiv dominikansk rom, skabt med passion og tradition. Rommen er opkaldt efter det historiske smuglerskib Kirk &amp; Sweeney, der under forbudstiden fragtede rom fra Caribien til USA – en arv, der i dag hyldes gennem denne luksuriøse aftapning. Destilleret af sukkerrørsmelasse og lagret på egetræsfade, leverer denne rom en fyldig og balanceret smagsoplevelse med noter af vanilje, tørret frugt, karamel og en diskret krydret afrunding. Gran Reserva udgaven udmærker sig ved sin bløde tekstur og komplekse aromaer – ideel til langsom nydelse.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk &amp; Sweeney Rum - Gran Reserva Superior', 'https://www.kokkensvinhus.dk/shop/kirk-sweeney-rum-gran-reserva-superior/', 499.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/07/Kirk-Sweeney-Gran-Reserve-superiur.jpg', 'Kirk &amp; Sweeney Gran Reserva Superior – Dominikansk rom i verdensklasse Kirk &amp; Sweeney Gran Reserva Superior er en førsteklasses dominikansk rom, destilleret af fin sukkerrørsmelasse og lagret på amerikanske egetræsfade. Denne rom repræsenterer det ypperste fra Kirk &amp; Sweeney-serien og byder på enestående dybde, balance og elegance. Opkaldt efter den historiske smuglerskonnert Kirk &amp; Sweeney, der i 1920’erne sejlede rom til USA under forbudstiden, kombinerer denne Gran Reserva Superior håndværk og arv i én eksklusiv flaske. Oplev rige lag af mørk karamel, vanilje, tørret frugt og krydderier, efterfulgt af en silkeblød finish med en snert af egetræ og kakao. En luksusrom til dem, der søger kvalitet og kompleksitet i hver dråbe. Perfekt som gave eller til dig, der ønsker en romoplevelse ud over det sædvanlige.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Espero Caribbean Banana &amp; Rum Liquer 40%', 'https://www.kokkensvinhus.dk/shop/espero-caribbean-banana-rum-liquer-40/', 329, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/04/Ron-espero-banana.jpg', 'Tropisk rom med fyldig banansmag og blød, afrundet sødme.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation XO 20th Anniversary 35 cl', 'https://www.kokkensvinhus.dk/shop/plantation-xo-20th-anniversary-35-cl/', 269, TRUE, 35, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2019/04/Plantation-XO.jpg', 'Leveres ikke i gaveæske som de hele flasker!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Centenario 1985 2nd Batch 43%', 'https://www.kokkensvinhus.dk/shop/ron-centenario-1985-2nd-batch-43/', 549, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/11/Centenario-1985.jpg', 'Ron Centenario Edición 1985 Cask Selection – ægte luksusrom fra Costa Rica Oplev Ron Centenario Edición 1985 Cask Selection, en eksklusiv rom fra Costa Rica skabt til den kræsne nyder. Denne limited edition rom er lagret på nøje udvalgte fade, der giver en dyb og kompleks smag med noter af karamel, vanilje, tørret frugt og et strejf af egetræ. Med sin silkebløde karakter og varme aroma er Centenario 1985 perfekt til efterårets rolige stunder, julens forkælelse eller som gave til romelskeren, der fortjener det bedste.Nyd den rent, over is eller som en elegant afslutning på en god middag.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cueva 1501 Sistema 30 Panama 40%', 'https://www.kokkensvinhus.dk/shop/ron-cueva-1501-sistema-30-panama-40/', 999, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/09/Cueva-1501-30-yo-Systema.jpg', 'LEVERES FRAGTFRIT I DK Til romdrikkeren der ved hvad alder betyder !', '2026-11-08 11:00:00+01');
