INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park rom, Calvados Finish Limited Edt.', 'https://www.kokkensvinhus.dk/shop/worthy-park-rom-calvados-finish-limited-edt/', 999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/worthy-park-calvados.jpg', 'En eksklusiv jamaicansk rom lagret på Calvados-fade, hvor tropisk sødme møder fransk frugtighed', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('A.H. Riise Black Larimar 45,2%', 'https://www.kokkensvinhus.dk/shop/a-h-riise-black-larimar/', 2399, TRUE, NULL, 45.2, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/01/A.H.-Riise-Black-Larimar.jpg', 'Oplev essensen af de Vestindiske Øer i hver dråbe af The Black Gem Collection, KLAR TIL LEVERING Kraftig duft, i starten appelsinskal, efterfulgt af sød honning og blød vanilje. I starten krydret appelsinskal, en “mørk” smag, let prikkende mynte, som omfavnes af vanilje. Bag det hele, dæmpet men distinkt eg. Gå ikke glip af chancen for at sikre dig en del af denne eksklusive samling. Bestil nu, og lad dig forføre af en smagsoplevelse uden lige! HUSK GRATIS LEVERING TIL EN POST-UDLEVERING NÆR DIG!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('A.H. Riise glas', 'https://www.kokkensvinhus.dk/shop/a-h-riise-glas/', 69, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/AH-RIISE-GLAS.jpg', 'A.H. Riise Rum Glass Tulipan ligger i colli a 6 stk', '2026-11-08 11:00:00+01');
