INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Old Pascas, Carrabean White Rum 37,5%', 'https://www.kokkensvinhus.dk/shop/old-pascas-carrabean-white-rum-375/', 149, TRUE, NULL, 37.5, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/01/Old-Pascas.jpg', 'Den perfekte party mixer rom. Får dine cocktail til at smage af Carribien !', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Patridom XO Ltd. Cherry Wine Cask Finish', 'https://www.kokkensvinhus.dk/shop/patridom-xo-ltd-cherry-wine-cask-finish/', 449, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Patridom-XO-Ltd.-Cherry-Wine-Cask-Finish.jpg', 'Patridom XO Limited Edition er en eksklusiv udgave af den premium rom, Patridom XO, der er fremstillet af frisk sukkerrørsaft og melasse. Den oprindelige rom er lagret i det tropiske klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition har dog fået en ekstra lagring på eks-cherry vinfade, hvilket giver rommen en ekstra frugtagtig kompleksitet. Patridom XO Cherry Wine Cask Finish blev aftappet i juni 2024 og der blev produceret 2237 flasker. &nbsp; Duft: Frisk og livlig med græsagtige undertoner, blødt afrundet af strejf af blød vanilje og en antydning af sød kirsebær. Smag: Delikat sød og blød med smag af modne kirsebær og blandede bær, der afsluttes med en lang, tør og tilfredsstil- lende eftersmag.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Patridom XO Ltd. Marsala Cask Finish', 'https://www.kokkensvinhus.dk/shop/patridom-xo-ltd-marsala-cask-finish/', 549, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Patridom-XO-Marsala-finish-1.jpg', 'Patridom XO Ltd. Marsala Wine Finish Patridom XO Ltd. Marsala Wine Finish er en eksklusiv premium rom fra det anerkendte mærke Patridom, designet til kræsne romelskere. Denne begrænsede udgave bygger på Patridom XO, en fyldig rom lavet af omhyggeligt udvalgt sukkerrørsaft og melasse. Rommen lagres i amerikanske og franske egetræsfade i Den Dominikanske Republik, hvor det tropiske klima giver den en unik kompleksitet. For at tilføre ekstra dybde gennemgår rommen en ekstra lagring i ex-Marsala fade, hvilket tilføjer cremede og fyldige noter til smagsprofilen. Når flasken åbnes, mødes du af aromaer af rig karamel og blød vanilje, med subtile strejf af tørrede frugter og en anelse tobak. Ved første sip vil du opleve en perfekt balance af cremet vanilje, sødt brunt sukker, moden abrikos og gylden honning. Denne eksklusive rom er kun produceret i 2237 flasker, hvilket gør den til en unik samlergenstand. Med dens komplekse smagslag og begrænsede tilgængelighed er Patridom XO Ltd. Marsala Wine Finish et must-have for dem, der søger en sofistikeret romoplevelse.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cristobal Amarone finish lim. edt. rom 43%', 'https://www.kokkensvinhus.dk/shop/ron-cristobal-amarone-finish-lim-edt-rom-43/', 599.95, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/02/Cristobal-amarone-finish.jpg', 'Noter af svesker, brun farin, lidt træ og et vinøst touch i aromaen fra Amarone-fadet.', '2026-11-08 11:00:00+01');
