INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Scotland DS/TS 2022 48% Virgin Oak', 'https://www.kokkensvinhus.dk/shop/sbs-scotland-ds-ts-2022-48-virgin-oak/', 599.95, TRUE, NULL, 48, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/10/SBS-Scotland.png', 'limited edition med blot 219 fl', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Ecuador 2016, Bourbon and Virgin Cask', 'https://www.kokkensvinhus.dk/shop/sbs-ecuador-2016-bourbon-and-virgin-cask/', 749, TRUE, NULL, 57, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/SBS-Ecuador-2016.jpg', 'SBS Ecuador 2016 Rum er en unik fadrom, der er fremstillet af melasse og destilleret i et kolonnedestillationsapparat i Ecuador i 2016. Efter destillering er rommen blevet lagret på både et bourbon-fad og et virgin-egefad, hvorefter den er blevet aftappet ved en styrke på 57% alkohol i august 2024. SBS står for "Single Barrel Rum" og produceres af den danske importør og uafhængige aftapper 1423 ApS. Denne velanskrevne romserie har været populær i flere år, og med de seneste udgivelser under "SBS Fall 2024" er antallet af forskellige aftapninger nu steget til over 200 siden starten.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Venezuela 2010 – 50%', 'https://www.kokkensvinhus.dk/shop/sbs-venezuela-2010-50/', 649.95, TRUE, NULL, 50, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/12/Venezuela-2010.png', 'Den venezuelanske romtradition er kendt for fyldige og aromatiske rom,', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS India 2016, 55%', 'https://www.kokkensvinhus.dk/shop/sbs-india-2016-55/', 799.95, TRUE, NULL, 55, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/10/SBS-INDIA.png', 'Rommen er destilleret i Indien og udvalgt som en enkelt fadlagring.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Smugglers Treasure Barbados White Oak 40%', 'https://www.kokkensvinhus.dk/shop/smugglers-treasure-barbados-white-oak-40/', 399.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/11/smugglers-treasure-barbados.jpg', 'Lækker aftapning fra det berømte Four Square destilleri på Barbados. En velafbalanceret rom med en fyldig og rig smag. Noter af vanilje, kokos og karamel kombineres med ristede skumfiduser!', '2026-11-08 11:00:00+01');
