INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Venezuela XO 25th Anniversary - Rum Nation', 'https://www.kokkensvinhus.dk/shop/venezuela-xo-25th-anniversary-rum-nation/', 499.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/03/Venezuela-25th-anniv.jpg', 'Fremragende valg for dem, der ønsker at udforske de fineste aspekter af venezuelansk rom.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Belize 2007 Rum 15yo Single Cask 55%,Bellamy''s Reserve', 'https://www.kokkensvinhus.dk/shop/belize-2007-rum-15yo-single-cask-55bellamys-reserve/', 999.95, TRUE, NULL, 55, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Bellamy-2007Belize.jpg', '&nbsp; Du Kan stadig nå at tilmelde dig vores Bellamy Smagning 28. feb!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Jamaica Clarendon 2007 Rum 15yo Single Cask 52%, Bellamy''s Reserve', 'https://www.kokkensvinhus.dk/shop/jamaica-clarendon-2007-rum-15yo-single-cask-52-bellamys-reserve/', 999.95, TRUE, NULL, 52, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Bellamy-2007-Jamai-Clarendon.jpg', '&nbsp; Du Kan stadig nå at tilmelde dig vores Bellamy Smagning 28. feb!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('RON SOSTENIBLE 15YO 46% La Isabela 2008', 'https://www.kokkensvinhus.dk/shop/ron-sostenible-15yo-46-la-isabela-2008/', 699, TRUE, NULL, 46, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/08/RonSos15.jpg', 'Samtlige rom i serien sendes fra den dominikanske republik om bord på et traditionelt sejlskib, der udelukkende drives af vindkraft; det vil sige ingen brændstof og ingen motorkraft. Flaskerne er fremstillet af 100% genbrugsglas, etiketterne er trykt på 100% genbrugspapir og vores nye, forbedrede prop er lavet af genanvendt kork, der ved tilsætningen af aktivt kul skaber en mindre CO2 udledning i produktionen.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ruby Panama Meets Port 8YO 45% Spirit Drink, Bellamy''s Reserve', 'https://www.kokkensvinhus.dk/shop/ruby-panama-meets-port-8yo-45-spirit-drink-bellamys-reserve/', 499.95, TRUE, NULL, 45, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Bellamy-Pan-meets-port.jpg', 'Bellamy''s Reserve Rum. Bellamy''s Reserve Rum har fokus på sjældne rom, udvalgte enkeltfade og særlige finishes. Formålet er at tilbyde unikke og let drikkelige. Bellamys Reserve henter omhyggeligt gamle og ekstraordinære årgangsfade til lagring for at skabe virkelig enestående rom. Målet er, at hver tår skal være en rejse gennem rommens rige historie og kultur, unikke smage og aromaer fra den respektive region i Caribien og Sydamerika. Ruby Panama Meets Port 8YO 45% Spirit Drink: En unik blanding af en 8-års column still-rom fra Panama og Reserve Ruby Port. Efter lagring på gamle bourbonfade blev den forsigtigt blandet med portvin i forholdet 10% rom og 90% rom. Herefter den lagret i gamle fade, der havde indeholdt Jamaica- rom og aftappet ved 45% alkohol.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Socializar Rom Dominikansk Rep  8 yo', 'https://www.kokkensvinhus.dk/shop/socializar-rom-dominikansk-rep-8-yo/', 479, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/08/Socializar-Rom-Dominikansk-Rep-8-yo.jpg', '“Socializar” essensen af forbindelse og fællesskab, som rom har fremmet i århundreder.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Tawny Panama Meets Port 8YO 45% Spirit Drink, Bellamy''s Reserve', 'https://www.kokkensvinhus.dk/shop/tawny-panama-meets-port-8yo-45-spirit-drink-bellamys-reserve/', 2499.95, TRUE, NULL, 45, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/09/Bellamy-Pan-meets-port.jpg', '&nbsp; Du Kan stadig nå at tilmelde dig vores Bellamy Smagning 28. feb!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rom-smagning Fre. 9.OKTOBER 2026 kl. 19.00', 'https://www.kokkensvinhus.dk/shop/rom-smagning-fre-9-oktober-2026-kl-19-00/', 349, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2025/10/romsmagning-9-okt-e1786361495603.png', 'Vi smager de nyeste trends. STADIG BILLETTER TIL WEFTERÅRETS ROM OPLEVELSE &nbsp;', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Panama Rum 18 y.o. 40%', 'https://www.kokkensvinhus.dk/shop/rum-nation-panama-rum-18-y-o-40/', 599, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/08/Panama18RN.jpg', 'Sød, frugtagtig og forfriskende. Sukkerrørsmelasse, chokolade, rosiner og igen en god balance mellem appelsinskal, cola og kokosnød.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Rare Rums Jamaica 10 y.o. 2013-2024, 59,9%', 'https://www.kokkensvinhus.dk/shop/rum-nation-rare-rums-jamaica-10-y-o-2013-2024-599/', 1099, TRUE, NULL, 59.9, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/08/RareRumsJamaica.jpg', 'Esteren er tydelig men ikke tung. Sødmefuld krydderi (som Five Spice), med noter af grillet ananas, stjerne anis, kakao.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Santa Teressa Bicentenario', 'https://www.kokkensvinhus.dk/shop/santa-teressa-bicentenario/', 2499, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/08/SantaTeresaBicen.jpg', 'En hyldest til rom-elskerne, Santa Teresas ældste solera rom med op til 80-årige rom som ingrediencer i blandingen. Rommen rammer gennemsnitlige en alder på 25 år. Kun 1.600 flasker produceres årligt af Santa Teresa Bicentenario AJ Vollmer Ron Anejo.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Jamaica  2020 NY-WK-Px Cask  52%', 'https://www.kokkensvinhus.dk/shop/sbs-jamaica-2020-ny-wk-px-cask-52/', 699, TRUE, NULL, 52, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/04/SBSJamaica20.jpg', 'Lækre modne frugter smelter sammen med subtile noter af acetone, suppleret med essensen af mandler og et strejf af tørret frugt. Noter af rosiner sammen med smagen af sød vin, understøttet af en tør tannin fornemmelse, kulminerende i en robust frugtig finish', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('SBS Origin Australia KLK 57%', 'https://www.kokkensvinhus.dk/shop/sbs-origin-australia-klk-57/', 449, TRUE, NULL, 57, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/04/SbsOriginAustralia.jpg', 'Ekstraordinært funky ester duft, ledsaget af den livlige essens af jordbær og den saftige sødme af modne pærer.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Favorite- Vieux VSOP Coeur AOC 40%', 'https://www.kokkensvinhus.dk/shop/la-favorite-vieux-vsop-coeur-aoc-40/', 449, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/01/Favorite4ans.jpg', 'Noget af det ypperligste Rhum Agricole der kan opdrives!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison du Rhum Paraguay 2009 sherry Finish Batch 4', 'https://www.kokkensvinhus.dk/shop/la-maison-du-rhum-paraguay-2009-sherry-finish-batch-4/', 649, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/maison_paraguay.jpg', 'La Maison du Rhum - Dugas, Frankrig. Til denne udgave fører Maison du Rhum os til Paraguay. Det er inden for Fortin-destilleriet, hvor romproduktionsprocessen er 100% organisk, at Maison du Rhum har valgt denne årgang, destilleret i 2009, efter at have draget fordel af en finish i sherry fade. Dens næse er intens og overdådig og dragende. Noterne af vanille og mocca fudge Dette er en utrolig spændende rom der viser hvor dygtig La Maison du Rhum er i deres udvælgelse af hver enkelt fad.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Navy Island Port Finisk Navy Str, 62,3% Jamaica', 'https://www.kokkensvinhus.dk/shop/navy-island-port-finisk-navy-str-623-jamaica/', 599, TRUE, NULL, 62.3, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/01/Navy-Island-Port-623.jpg', 'Rom for fuld styrke! Og med lækker intens portvinsfinish. &nbsp; &nbsp;', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa La Pasion Heavenly cask collection', 'https://www.kokkensvinhus.dk/shop/ron-zacapa-la-pasion-heavently-cask-collection/', 829, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/10/ZacapaLaPasion.jpg', 'La Pasion er den 4 og sidste aftapning i Heavenly cask collection serien fra Ron Zacapa. La Pasion er som Zacapa''s andre aftapning Solera rom og har fået finish på et Ex-Pedro Ximenex sherry fad.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Mombacho 12 YO reserve especial', 'https://www.kokkensvinhus.dk/shop/mombacho-12-yo-reserve-especial/', 499, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/07/Monbacho-12yo-reserve-special.png', 'Køb Mombacho 12 YO res especial til en VILD pris !', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Nacional rums of Jamaica 57% Cambridge STCE 2010', 'https://www.kokkensvinhus.dk/shop/nacional-rums-of-jamaica-57-cambridge-stce-2010/', 1699, TRUE, NULL, 57, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/07/Cambridge.jpg', 'Fyldig og cremet, men tør. Noter af toffee, valnød, ananas og kakifrugt. En lang og berusende finish med hints af crème brulée, tjære og kamfer.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Port Morant 2008, 0,7ltr 43%', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-port-morant-2008-07ltr-43/', 999, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/01/PortMo08.jpg', 'Bristol Classic Spirits med Rom Legende John Barrett i spidsen, har specialiseret sig over en lang årrække, at udvælge de bedste fade, fra ikoniske rom destillerier i Caribien, hvortil rommen lagre under tropiske forhold det meste af deres liv, hvor så den fragtes til Storbritannien, hvor rommen lagre de sidste måneder, inden de tappes.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cane Island Trinidad Limited edt.Sherry finish 8 y.o. 43%', 'https://www.kokkensvinhus.dk/shop/cane-island-trinidad-limited-edt-sherry-finish-8-y-o-43/', 499, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/02/Trinidad8Lim.jpg', 'Flot, mørk og ravfarvet 8-års rom med meget behagelige hint af egetræ og modne bananer. Flot balance mellem det krydrede præg fra egetræet og en delikat sødme, efterfulgt af en nuanceret finish, med de krydrede nuancer fra de Oloroso sherry fade rommen har ligget 9 måneder på.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano reserva 18 limited, Venezuela', 'https://www.kokkensvinhus.dk/shop/carupano-reserva-18-limited-venezuela/', 399.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/08/Curapano.png', 'Eksklusiv venezuelansk 18 års rom med dybde, mørk karamel, vanilje og tørret frugt – elegant, fyldig og lang.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Sealander Very Special Aged rum', 'https://www.kokkensvinhus.dk/shop/plantation-sealander-very-special-aged-rum/', 449, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/10/Sealander.jpg', 'På én gang en delikat og fyldig Rom, med stor sødme og noter af kløverhonning, vanilje og sveske, men alligevel har en flot karakter af fad og dermed en smule tannin, der klæder rommen rigtig godt.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('PROVIDENCE 2019 3 ans 2022 52 % Haiti Velier SpA', 'https://www.kokkensvinhus.dk/shop/providence-2019-3-ans-2022-52-vellier-haiti/', 999, TRUE, NULL, 52, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/03/PROVIDENCE-2019.jpg', 'Du få her en perfekt haiti rum der er Let gylden.i farven og med masser af Florale noter (rose, geranium) der blander sig med tropisk frugt som grillet ananas og banan. Rom smagen er umiskendelig og giver en tyk og cremet mundfølelse, med noter af tobak, brændt banan, blomster og varme krydderier.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chasing Casks Belize 2009, Marsala Finish 12 YO 48,%', 'https://www.kokkensvinhus.dk/shop/chasing-casks-belize-2009-marsala-finish-12-yo-48/', 899, TRUE, NULL, 48, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/12/chasing-cask-belize-marsala.jpg', 'Chassing Cask er en ny Rom og Whisky aftapper, der går efter at aftappe ny spændende smagfulde enten Rom eller Whisky, Chassing søger via personlig selektion af både rommen og de fade de færdigøre dem på at fremtvinge nye spændende romsmage, der oftest kun aftappes i 40 til 100 eksemplarer ”LET YOUR MIND FLOURISH” hedder deres første serie der kommer til at bestå af 3 varianter. Flaskens indhold afspejles smagsmæssigt altid i illustration på flaskens label, Der er designet af Agnethe Hahn. ”LET YOUR MIND FLOURISH” LAD TANKERNE BLOMSTRE ! I deres første udgave er der valgt en 12 års lageret Belize rom der er trukket til Danmark for at lagre på små Marsala fade i 6 måneder, hvorefter den er er vandet ned til 48% alk. For at smagsnoterne som vanilliefudge, ananas og hvid chokolade klarest i smagerens mind set!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chasing Casks Panama 13 YO, Malaga Finish 54,%', 'https://www.kokkensvinhus.dk/shop/chasing-casks-panama-8-yo-malaga-finish-54/', 1199, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/03/CC-Panama-e1680183424306.jpg', 'Kun 54 fl tappet!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Esclavo 12  20 cl 40%', 'https://www.kokkensvinhus.dk/shop/ron-esclavo-12-20-cl-40/', 139, TRUE, 20, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/05/Esclavo12.jpg', 'Rommen lagres i Den Dominikanske Republiks tropiske klima, i amerikanske og franske egetræsfade, i en periode fra seks til tolv år. "Tunge aromaer af brun sukker, vanilje og kokosnød, dog mild og afbalanceret"', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Esclavo XO 20 cl 42%', 'https://www.kokkensvinhus.dk/shop/ron-esclavo-xo-20-cl-42/', 179, TRUE, 20, 42, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/05/EsclavoXo.jpg', 'Rommen lagres i Den Dominikanske Republiks tropiske klima, i amerikanske og franske egetræsfade, i en periode fra tolv til femten år. Fyldig og afbalanceret med en delikat frugtig note, kombineret med et strejf af vanilje og kokosnød.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Espero Caribean Orange 40% Dom. Rep', 'https://www.kokkensvinhus.dk/shop/ron-espero-caribean-orange-40-dom-rep/', 329, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2026/04/Espero-Orange-Caribbean-Licor.webp', 'Eksklusiv caribisk rom med frisk appelsintwist og blød, fyldig smag.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Sostenible Tokaji Experimental Cask 43 %', 'https://www.kokkensvinhus.dk/shop/ron-sostenible-tokaji-experimental-cask-43/', 549, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/03/ron-sostanible-experiment-port-e1709718738820.jpg', 'Ron Sostenible Experimental Cask SeriesTokaji Cask 05/04/24 Hvorfor er der så meget valg og variation, når man køber rom? Selvom destillerierne og aftapperne ikke har for mange muligheder, når det kommer til råvaren på grund af fokus på sukkerrør, kan de lade kreativiteten få frit løb med de øvrige detaljer i produktionen. Frem for alt giver opbevaring af rom fra Caribien eller resten af ​​verden virksomheder en masse muligheder for at eksperimentere. Bare tag det lovende Ron Sostenible Experimental Cask Series Tokaji Cask. En dominikansk rom med en moderne karakter, den fik chancen for at blive lagret på to forskellige typer fade. Dette gør også kendere nysgerrige på højkvalitetsnyheden i et begrænset oplag. kun 950 fl Det sofistikerede Ron Sostenible Experimental Cask Series Tokaji Cask fortjener fuld opmærksomhed. For al moderne caribisk rom skylder vi det til et dansk firma kaldet A Clean Spirit. Deres mål er at tilbyde rom og anden spiritus fra bæredygtig produktion. Til dette formål har virksomheden stolet på et af de mest bæredygtige destillerier til Ron Sostenible Experimental Cask Series Tokaji Cask. Rommen fra Den Dominikanske Republik er baseret på sukkerrør dyrket uden kemikalier. Efter destillationen modnedes den på amerikanske bourbonfade i otte år. Han var påvirket af det lokale tropiske klima. Rommen blev derefter transporteret til Europa med sejlskib, hvor den blev lagret på Ungarske Tokaji-fade i et kontinentalt klima. Det er denne efterbehandling, der har givet det bestemte noget.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Sostenible Rioja " The Conscious Choice" 40 %', 'https://www.kokkensvinhus.dk/shop/ron-sostenible-rioja-the-conscious-choice-40/', 549, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/04/RiojaCask.jpg', 'Denne aftapning er destilleret af frisk sukkerrørsjuice og derefter lagt 8 år på ex-Bourbon fade, inden den så ligges på Rioja fade for ekstra fadlagring.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Royal Cane Fiji 2004, 18YO 60,2%', 'https://www.kokkensvinhus.dk/shop/royal-cane-fiji-2004-18yo-602/', 1999, TRUE, NULL, 60.2, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Royal-Cane-Fiji-2004-002.jpg', 'En helt unik Pot Still rom fra den smukke ø, Fiji, i det sydlige Stillehav.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Royal Cane Guadeloupe 1998, 24YO 51,5%', 'https://www.kokkensvinhus.dk/shop/royal-cane-guadeloupe-1998-24yo-515/', 1999, TRUE, NULL, 51.5, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Royal-Cane-Guadeloupe-1998-002.jpg', 'Kun 265 flasker. Forvent en rig, blomstret, citrusagtig rom med melassekarakter og et strejf af røg.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Saint James 12 år Martinique Rhum - MBWS', 'https://www.kokkensvinhus.dk/shop/saint-james-12-aar-martinique-rhum-mbws/', 749, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/01/SaintJ12.jpg', 'En kraftfuld aromatisk kompleksitet. Fra den langvarige modning på egetræsfade udspringer fyldige, afrundede og træagtige toner i næsen, mens smagsløgene mødes af ristede noter afbalanceret med en udtalt krydret smag af muskatnød, der er afrundet med en eftersmag af blomme og kanel.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Saint James 15 år Martinique Rhum - MBWS', 'https://www.kokkensvinhus.dk/shop/saint-james-15-aar-martinique-rhum-mbws/', 1199, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/01/SaintJ15.jpg', 'En smagsoplevelse ud over det sædvanlige. Tanniner og træ dominerer med underspillede noter samt overmodne frugter i smagen, mens næsen mødes af jord- og træagtige toner kombineret med ristede og grillede aromaer.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('TDSC Columbian Single Cask 30YO', 'https://www.kokkensvinhus.dk/shop/tdsc-columbian-single-cask-30yo/', 3499, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/10/Colombia30.jpg', 'På trods af en ”næse” der svømmer i karamel og sukker, så er rommen ret tør på tungen – kraftig, kompleks og med en lang, lang eftersmag. Her fornemmes også gammelt træ, nellike og ægte kanel. En smagsoplevelse af de helt store!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Demerara Rum Port Morant 2003, 13 Years Old Silver seal 51 %', 'https://www.kokkensvinhus.dk/shop/demerara-rum-port-morant-2003-13-years-old-silver-seal-51/', 1999, TRUE, NULL, 51, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/10/Demenara-Rum-Port-Morant-2003-13-Years-Old-Silver-seal-51-.jpg', '13 År Gammel Rom', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico NO 3 Batch Pot Still Rum', 'https://www.kokkensvinhus.dk/shop/diplomatico-no-3-batch-pot-still-rum-2/', 599, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/diplomatico-batch-3.jpg', 'Fra The Distillery Collection kommer hermed nummer 3 i serien : No 3 Pot Still Rum Kokkens Vinhus har forhandlet Diplomatico i mange år og vi har et bredt udvalg af varianter som alle sammen på hver sin måde er helt fantastiske, og fra 2019 er vi ydermere blevet udvalgt som forhandler til at være Diplomatico-ambassadør med ekstra stort fokus på netop Diplomatico. Den velkendte Diplomatico rom, der hører hjemme i Venezuela ved foden af Andes-bjergene, har lanceret en “Distillery Collection” serie (No 1 og No 2), hvor både fremstillingsmetoden og de anvendte destilleringsapperater er forskellige, og nu har de frigivet nummer 3 i serien som er lavet på Ren Pot Still-rom. Den har en fantastisk næse med gyldne frugter, caramel, vanilje, tørrede frugter, marzarinkage og mandler. I munden er den intens og eksplosiv med stor fylde og dybde. Finishen er ultra-lang og slynger sig flot i bølger af kærlighed.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico No. 1 Batch Kettle Rum', 'https://www.kokkensvinhus.dk/shop/diplomatico-no-1-batch-kettle-rum-2/', 549, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/diplomatico-1.jpg', 'Den velkendte Diplomatico rom, der h&oslash;rer hjemme i Venezuela ved foden af Andes-bjergene, har lanceret en "Distillery Collection" serie (No 1 og No 2), hvor b&aring;de fremstillingsmetoden og de anvendte destilleringsapperater er forskellige.Diplomatico Distillery Collection No 1 Batch Kettle Rum er prim&aelig;rt baseret p&aring; sukkerr&oslash;rshonning, og destilleringen er foreg&aring;et i en "Semi-artisanal Batch Kettle Still", der blev bragt fra Canada til Diplomatico''s La Miel destilleri i 1959. Den 6 &aring;r lange lagring af rommen er foreg&aring;et i amerikanske white oak fade, der tidligere har v&aelig;ret anvendt til bourbon og malt whisky. Diplomatico Distillery Collection No 1 Batch Kettle Rum har en "semi-heavy" smagsprofil med noter af vanilje, kirseb&aelig;r, jordb&aelig;r og banan. Denne rom er fremstillet i et begr&aelig;nset antal.Teknisk forklaring p&aring; Batch Kettle: "This system is characterized by a batch distillation, which means that a certain volume of fermented liquid is introduced for distillation and, as this is gradually depleted, it leaves a residue or water, which is drained off to be added to the next batch. This system is controlled by the Maestros Roneros, and is considered a semi- artisanal system."Limiteret udgave!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico No. 2 Barbet Rum', 'https://www.kokkensvinhus.dk/shop/diplomatico-no-2-barbet-rum-2/', 549, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/dipn2..jpg', 'Kokkens Vinhus har forhandlet Diplomatico i mange &aring;r og vi har et bredt udvalg af varianter som alle sammen p&aring; hver sin m&aring;de er helt fantastiske, og fra 2019 er vi ydermere&nbsp; blevet udvalgt som forhandler til at v&aelig;re Diplomatico-ambassad&oslash;r med ekstra stort fokus p&aring; netop Diplomatico.&nbsp;Den velkendte Diplomatico rom, der h&oslash;rer hjemme i Venezuela ved foden af Andes-bjergene, har lanceret en "Distillery Collection" serie (No 1 og No 2), hvor b&aring;de fremstillingsmetoden og de anvendte destilleringsapperater er forskellige.Diplomatico Distillery Collection No 2 Barbet Rum er baseret p&aring; melasse, og destilleringen er foreg&aring;et i en "Barbet Column Still", der blev bragt fra Frankrig til Diplomatico''s La Miel destilleri i 1959. Den 4 &aring;r lange lagring af rommen er foreg&aring;et i amerikanske white oak fade, der tidligere har v&aelig;ret anvendt til bourbon og malt whisky. Diplomatico Distillery Collection No 2 Barbet Rum har en "light" smagsprofil med noter af egetr&aelig;, citrus og tropisk frugt. Denne rom er fremstillet i et begr&aelig;nset antal.Teknisk forklaring p&aring; Barbet Column Still: "This system consists of two columns: the Aldehyde Column, in which the undesired elements are separated from the rest of the liquid, and the Rectifying Column where only the desired elements are kept. This rectification system is not found in other traditional column systems. It is unique to this design and is what gives the characteristic fruity profile to the distillate obtained."&nbsp;', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Single Vintage 2007', 'https://www.kokkensvinhus.dk/shop/diplomatico-single-vintage-2007/', 1099, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/10/Diplomatico-Single-Vintage-2007.jpg', 'Vintage 2007 er produceret af nøje og helt unikke fade, udvalgt af Masterblenderen. Fadene skal hver i sær have noget helt særegent over sig for overhoved at blive nomineret til at ind gå i det endelig blend. Selektionen er hård og flere fade bliver skilt fra i runde 2 og 3. På denne måde hæves bundniveauet markant.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Caribbean Luxus 10 + 5', 'https://www.kokkensvinhus.dk/shop/dos-maderas-caribbean-luxus-10-5-2/', 1799, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/rom026931-200x200_1.jpg', 'Master blenderen udv&aelig;lger n&oslash;je mellem de mest eksklusive rom fra Barbados og Guyana. N&aring;r den &oslash;nskede blanding er fundet, lagrer man rommen 10 &aring;r i Caribien.', '2026-11-08 11:00:00+01');
