INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Unión', 'https://www.kokkensvinhus.dk/shop/havana-club-union-2/', 3999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/havana-club-union.jpg', 'LEGENDARISK ROM FRA HAVANA CLUB', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Glostrup Open Tap , Panama 12yo finish on Danish oak lim.edt.', 'https://www.kokkensvinhus.dk/shop/glostrup-open-tap-panama-12yo-finish-on-danish-oak-lim-edt/', 699, TRUE, NULL, 54.3, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/12/Glostrup-open-tap-e1639643961586.jpg', 'For første gang nogensinde frigives en ægte caribisk rom lageret i Glostrup og de bedste fade af DANSK egetræ! I den tidligere sommer 2021 besluttede 5 romentusiaster og Kokkens Vinhus at verden ikke bare kunne stå stille, selv midt i en corana-tid. Sammen indkøbte vi både fad og rom og d. 9. juli blev rom hældt på et helt nyt egetræsfad lavet af det bedste danske eg. Gang på gang måtte entusiasterne mødes og udsætte deres ganer for nærmest utænkelig smagsoplevelser, men 4 måneder senere . var de klar! Rommen kunne tappes og nu gik de i gang med justering ALLE var enige VI TILSÆTTER IKKE SUKKER! Så vi har kun fin justeret og kommet op med en rigtig HERRE-ROM, som en hver dame kan forelske sig i &#x1f60a; 54,3% alkohol og den bære det med stolthed. Smagsnuancer af sultana, eksotiske frugter, engelsk fudge og danske piraters storheds tid passere revue ! &nbsp; Største delen af Glostrup Open Tap er naturligvis solgt internt, men vi har stadig enkelte tilbage til de hurtigste. Så skynd dig hvis du vil opleve denne unike rom og kom ned og få historien om HVORFOR den hedder Glostrup Open Tap?', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Skab din egen rom - PRIVATE CASK', 'https://www.kokkensvinhus.dk/shop/skab-din-egen-rom/', 2999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/08/5.jpg', 'Dette fad er åbnet for andele 11.April Hver med til at vælge indhold og type det kunn ef.eks se således ud :-) Rom: Australien? Fad: Marsala ? Lagringsted: Glostrup ? Lagringstid: xx år + det vi bliver enige om 10 Fad-andele tilsalg VI PÅFYLDER FAD FREDAG D. XXXX MELLEM 16-18.00', '2026-11-08 11:00:00+01');
