INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Favorite La Flibuste 2000 Cuvee Speciale Vielle en Futs', 'https://www.kokkensvinhus.dk/shop/la-favorite-la-flibuste-2000-cuvee-speciale-vielle-en-futs/', 3499, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/09/Flibuste2000.jpg', 'Cuvée Spéciale de la Flibuste er Martiniques svar på Bordeaux’ Château Mouton-Rothschild. Det er måske den bedste rhûm agricole, der overhovedet produceres.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Favorite Millesime 2013 Selection de Futs', 'https://www.kokkensvinhus.dk/shop/la-favorite-millesime-2013-selection-de-futs/', 1599, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2023/01/FavoriteMil2013.jpg', 'Habitation La Favorite - Martinique. Destilleriet La Favorite er beliggende i La Lamentin i udkanten af Fort-de-France, som er hovedstaden på den caribiske ø Martinique. Det er et af de mest autentiske steder man overhovedet kan forestille sig, og man føler sig sat hundrede år tilbage i tiden, når man går rundt og iagttager produktionen på dette lille fantastiske og charmerende destilleri, som drives af familien Dormoy. Man skal dog ikke lade sig narre af synet af det mere end 100 år gamle produktionsanlæg. Det er nemlig hele hemmeligheden bag nogle af verdens bedste rhûm agricole. Vi tør godt at påstå, at La Favorite producerer den bedste rhûm på Martinique. Denne vintage udgave et destilleret i 2013 og har lagret tropisk i 8 år, inden den tappes uden nedvanding! Agricole er destilleret på sukkerørsjuice og er en mere frisk og frugtig romstil, hvor La Favorite er i førersædet!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Favorite, Vieux Privilege pour Lulu - 41,3 %', 'https://www.kokkensvinhus.dk/shop/la-favorite-vieux-privilege-pour-lulu-413-2/', 1449, TRUE, NULL, 41.3, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/rhum-la-favorite-privil_ge-pour-lulu.jpg', 'Martinique - Tør og ÆGTE rom &nbsp; 1999 Vintage', '2026-11-08 11:00:00+01');
