INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Oliver''s Maximo Solera 41 %', 'https://www.kokkensvinhus.dk/shop/olivers-maximo-solera-41/', 599.95, TRUE, NULL, 41, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/05/Maximo.jpg', 'Oliver''s Maximo Solera Rum. Maximo Solera er rom fra den dominikanske republik, den er lagret efter solera metoden. Rommen har ligget på franske og amerikanske egetræsfade, for derefter at slutte sin lagring af i Pedro Ximenez sherry fade, for at give den sødme, krydderi og fedme. En rigtig rigtig dejlig rom, der har en tilpas mængde søde, en flot rom karakter og en god lang finish, der bliver hængende. OLIVER &amp; OLIVER er en familieejet Uafhængig Romaftapper af cubansk oprindelse, beliggende i Den Dominikanske Republik, som siden 1874, har specialiseret sig i Rom.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Panama 2009, 63,2% Raw cask Blackadder', 'https://www.kokkensvinhus.dk/shop/panama-2009-632-raw-cask-blackadder-2/', 899, TRUE, NULL, 63.2, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Panama-2009-632-Raw-cask-Blackadder.jpg', 'En fremragende dram, der let kan drikkes ren på trods af de 63,2% alkohol, men der kan også tilsættes lidt vand, som får rommen til at åbne sig yderligere.', '2026-11-08 11:00:00+01');
