INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantaray XO 20th Anniversary', 'https://www.kokkensvinhus.dk/shop/plantation-xo-20th-anniversary-2/', 449, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Plantation-XO-20-annivers.jpg', 'PlantarayXO 20th Anniversary - sød mørk rom i topklasse Rommen er lagret på flere forskellige fadtyper, deriblandt det efterhånden velkendte cognacfad (Plantarays signatur, om man vil) men også helt nye, ubrugte fade af amerikansk hvid-eg. Disse fade giver yderligere vaniljenoter til Barbados-rommen, som i forvejen svømmer i tropisk frugt og kokosnød. I glasset er rommen flot bronze-farvet og i næsen er den meget aromatisk og frugtig, med ananas, vaniljestang og kokostoppe. Rommen er blid og venlig i munden og udfolder sig flot med mazarin, tørret mango, ananas, papaya og Bounty-chokolade. Maison Ferrand blev skabt med én mission: at bevare Frankrigs gastronomiske skatte. Alexandre har gjort en dyd ud af at ånde liv i gamle og for længst glemte traditioner, og den evigt lærelystne franskmand er blandt andet kendt for at opstøve og opkøbe gamle arkiver fra konkursramte huse, for at lære mere om fortidens produktionsmetoder. Men hos Ferrand forstår man også værdien af fornyelse, og i dag værdsættes innovation lige så højt som tradition. Sidenhen har foretagendet bredt sig ud over Frankrigs landegrænser, og i dag er Ferrand måske mest kendt for sin serie af rom. Under navnet Plantation opkøber Alexandre rom fra mange forskellige lande i Caribien og efterlagrer dem i Frankrig på cognac-fade. I serien findes rom til både begynderen og kenderen, til både daiquirien og Glencairn-glasset. Firmaet købte i 2017 Barbados-destilleriet West Indies Rum Distillery, og har nu altså også egen romproduktion helt fra bunden.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser’s British Navy Rum Selected Aged 151 på 75,5%,', 'https://www.kokkensvinhus.dk/shop/pussers-british-navy-rum-selected-aged-151-paa-755-2/', 439, TRUE, NULL, 75.5, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/pusser_s_british_navy_rum_selected_aged_151.jpg', 'Fuld power og dog, meget afrundet med noter af sirupagtig krydderi og frugt, l&aelig;der, t&oslash;rrede sultanas, bl&oslash;d eg og Engelsk lakrids &nbsp; Hejmkommer 5.marts 2021', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Richland Rum batch 95- Old Georgia Rum', 'https://www.kokkensvinhus.dk/shop/richland-rum-batch-95-old-georgia-rum-2/', 749, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/rich95..jpg', '', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Richland Terrapin IPA Cask 43%', 'https://www.kokkensvinhus.dk/shop/richland-terrapin-ipa-cask-43-2/', 919, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/terrepin..jpg', 'Richland Rum - Georgia, Usa. Richland Rum er en autentisk, naturlig rom, der er fremstillet i Georgia, USA. Rommen er en single estate rom, hvilket betyder, at rommen er lavet og produceret på ét og samme sted. Richland rom er lavet på sukkerrørsjuice fra egen sukkerplantage, som er blevet gæret og destilleret på plantagen. Destilleringen foregår i en traditionel kobber pot still. Til sidst er rommen lagret på stedet i nye amerikanske egetræsfade. Aftapningen foregår direkte fra fad til flaske uden nogen form for blanding, og hele fremstillingen foregår lokalt og baseret på egne materialer. Der bliver ikke tilsat noget til produktet undervejs i produktionen. Her er der tale om en helt naturlig rom. Denne aftapning er helt ny på det danske marked, blev introduceret på vores Richland smagning i oktober, direkte fløjet ind fra Georgia med Erik og Karin Vonk! Det unikke ved denne Rom er at den har ligget 3 år på fade, hvor fadet derefter er blevet sendt til Terrepin bryggeriet, som lånte fadene til at lagre deres IPA øl på, for så at returnere fadene til Richland, for at lagre rommen yderligere et år! Og hvilken unik rom der er kommet ud af det! En rom som byder på citrusnoter, grapefrugt i næsen, som hurtigt mødes at karamel, vanilje og bær. Det er uden tvivl en af de mest interessante rom vi har smagt meget længe!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Centenario  Edication Limitada 30 år', 'https://www.kokkensvinhus.dk/shop/ron-centenario-edication-limitada-30-aar-2/', 1399, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/centenario-30-ans_grande.jpg', 'Eksklusiv rom fra Costa Rica – Der byder på dybde, sødme og perfekt balance efter op til 30 års lagring. En luksusrom til ægte connaisseurs.', '2026-11-08 11:00:00+01');
