INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Centenario Grand Reserva 25, 40 %', 'https://www.kokkensvinhus.dk/shop/ron-centenario-grand-reserva-25-40/', 649, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Centenario-25yo.jpg', 'Denne Solera Rom er sød og elegant med en rig aroma af tropiske frugter, melasse, tobak, og eg. Smagen er blød med vanilje og sød frugtsmag ledsaget af sarte noter af træ og citrus. Farven er som mørk rav.En fantastisk rom.', '2026-11-08 11:00:00+01');
