INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cihuatan Xaman XO Rum 40% El Salvador', 'https://www.kokkensvinhus.dk/shop/ron-cihuatan-xaman-xo-rum-40-el-salvador/', 989, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/09/Xaman..jpg', 'UDGÅR DESVÆRRE! Denne rom fra El Salvador fra højeste hylde! Lagret i 16 år, de første 15 på Ex-Bourbon fade og derefter 1 år på Maya Ceiba-fade, som er en træsort der findes på de amerikanske kontinenter, det er også kendt som silkebomuldstræet.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cristobal NINA', 'https://www.kokkensvinhus.dk/shop/ron-cristobal-nina-2/', 349, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/CristobalNina.jpg', '8-12 år, lagret tropisk der afrundes med hints af frisk eg og creme brulée.', '2026-11-08 11:00:00+01');
