INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Santos Dumont Rum XO', 'https://www.kokkensvinhus.dk/shop/santos-dumont-rum-xo-2/', 499.95, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/santos-dumont-rum-xo.jpg', 'En raritet af en rom fra Brasilien, som sjældent ses. Før den gamle, lagrede rom tappes på flaske har den gennemgået en "Triple Cask Maturation", altså en modning på 3 forskellige fade. På disse fade har der tidligere lagret PX sherry, portvin og Bourbon. De 3 fadtyper bidrager med hver sit sær-præg til det færdige produkt. Der tappes kun ét fad af gangen og på hver flaske er der påtrykt fadnummer og flaskenummer. Santos Dumont XO er en lækker, sød og fyldig rom, hvor man oplever indtryk af vanille, kokos, karamel, sukkerrør, brun farin. Rommen har en lang og sødmefuld finish med et let tropisk præg', '2026-11-08 11:00:00+01');
