INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Unhiq XO Rom 50Cl.', 'https://www.kokkensvinhus.dk/shop/unhiq-xo-rom-50cl-2/', 999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/unhiq-xo.jpg', 'De sidste aftapninger efter gammel lovgivning indeen det nye romregel sæt træder i kraft! &nbsp; I smagen er her mange forskellige ting der udfordrer. Bl.a. er her en meget ”mørk” smag, som jeg tror, kommer fra et fad der har været udsat for voldsom toasting. Den er lidt mere ”lige på og hård” end Puntacana Club XOX 50 Aniversario Oporto, men har samtidig også lidt mere at byde på i smagen. Den er mindre sød og lidt mere tør – også en anelse mere tør end Puntacana Club XOX. Den har yderligere en eksploderende effekt i munden – dejlig oplevelse! Rommen her er mere udfordrende end mange af de sødere rom på trods af at sødmen bestemt er tilstedeværende. Den udfordre – dog uden at være ubehagelig eller for krævende. Den vil med sikkerhed falde i god jord hos ham/hende, der ikke ønsker en vildt sød rom og sætter pris på en mere kompleks rom. Det er nemlig en meget kompleks oplevelse, at drikke Unhiq XO Malt Rum. "', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Watt Rum C.A.D.C SA Venezuelan Rum 16 y.o. 57,1%', 'https://www.kokkensvinhus.dk/shop/watt-rum-c-a-d-c-sa-venezuelan-rum-16-y-o-571/', 1199, TRUE, NULL, 57.1, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/03/WattRum..jpg', 'Mark Watt har udvalgt en venezuelansk Rom, der spark R...! Brag af en Rom!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park Estate St. Catherine, WPE-2017 3YO Jamaica', 'https://www.kokkensvinhus.dk/shop/worthy-park-estate-st-catherine-wpe-2017-3yo-jamaica/', 649, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Worthy-Park-Estate-St.-Catherine-WPE-2017-3YO.jpg', 'Worthy Park Estate - Jamaica. Fra Worthy Park kommer denne helt unikke aftapning af Jamaica-rom. Worthy Park er toppen af poppe, og ikke mindst deres Special Cask Series, er en af grundende. her udvælger masterblenderen det bedste af det bedste. Denne udgave er et specifikt fad med nummer 1610. Allerede efter 3 år har dette unikke fad udviklet sig til en smuk Jamaica-rom. Fuld af aromatik, smagsdybde og kompleksitet. Helt unikt!', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park Single Est. Reserve Jamaica Rum 45%', 'https://www.kokkensvinhus.dk/shop/worthy-park-single-est-reserve-jamaica-rum-45-2/', 495, TRUE, NULL, 45, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/worthy-park-jamaica-est.-reserve.jpg', 'Worthy Park Estate - Jamaica. Worthy Park Single Estate Reserve Rum er produceret hos Worthy Park Estate, der har destilleret den melasse-baserede rom på en kobber pot still. Herefter er rommen lagret i ex-bourbonfade af hvid amerikansk eg imellem 6 og 10 år og afslutningsvis blendet. Rommen er hverken tilsat sukker eller andre tilsætningsstoffer og Worthy Park Single Estate Reserve Rum bruger kun en meget lille smule karamel for at udligne farven og opnå ensartethed på flaskerne. Det er altså en meget ren og autentisk Jamaica rom med fuldt aromaspektrum og et rigtig godt køb til prisen.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park Special Cask Series MADEIRA 2010 Jamaica', 'https://www.kokkensvinhus.dk/shop/worthy-park-special-cask-series-madeira-2010-jamaica/', 649, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Worthy-Park-Cask-Series-Madeira-2010.jpg', 'UNIK ROM FRA JAMAICA', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Classic Port Morant 1999, 16 år American Oak.', 'https://www.kokkensvinhus.dk/shop/bristol-classic-port-morant-1999-16-aar-american-oak-2/', 1999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/port-morant-1999.jpg', 'Denne Port Morant rom er fra Guyana. Guyana er det eneste sted, hvor der findes et double wooden pot still. Oprindeligt tilhørte dette pot still Port Morant destilleriet, der blev bygget i 1732 ved Demerara floden, men da Port Morant lukkede, blev det opkøbt af Diamond Distillery, som i dag er det eneste destilleri i Guyana.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Enmore Still 1988', 'https://www.kokkensvinhus.dk/shop/bristol-enmore-still-1988-2/', 2999, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/bristol-enmore-still-guyana-1988.jpg', 'UNIK ROM FRA BRISTOL - ENMORE STILL 1988 - Classic Demerara rom - Lagret på amerikansk eg - Meget bleg farve - Intens krydret næse og tør lang eftersmag. Enmore Estate i Guyana, kan dateres tilbage til 1840, men da industrien har ændret sig over årene, er Enmore Stills flyttet til nye placeringer. Nu hvor de blevet til en del af Demerara Distillers har Enmore Stills travlt med at producere deres unikke rom. Det gør de på Diamond Distillery i Georgetown. Denne rom, der blev destilleret i 1988 på pot still, er et klassisk eksempel på den fine Demerara Rum. Den har kun lagret i brugte amerikanske Bourbon fade. Den blege gyldne farve er usædvanligt for en 20 år gammel rom. Lys i farven, men fyldt med duft af frugt, brændt sukker og træ giver en introduktion til en tør dyb smag af ristet krydderi, alkohol og en god kontrolleret smag, med god vægt og lang tør eftersmag. En fin rom som måske ikke vil smage alle, men et sandt eksempel på det enkelte destilleris kunst. Nyd den stille og roligt i sofaen og oplev den sande Demerara. FÅ FLASKER TILBAGE', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Port Morant 25 år (1990)', 'https://www.kokkensvinhus.dk/shop/bristol-port-morant-25-aar-1990-2/', 3499, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/port-morant-25.jpg', 'Finish på Oloroso sherry fade og lagret fulde 25 år', '2026-11-08 11:00:00+01');
