INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Caroni Blended 1999 Trinidad&amp;Tobago 43%', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-caroni-blended-1999-trinidadtobago-43-2/', 2975, TRUE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/bristol-spirits-caroni-blended-1999-trinidadtobago-40.jpg', 'Meget afbalanceret og mild med en antydning af mineraler, eg og en let bitterhed til sidst.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Jamaica Trelawney 2009-2021, 47,5%', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-jamaica-trelawney-2009-2021-475/', 1499, TRUE, NULL, 47.5, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/06/JamaicaTrelawny.jpg', 'Super lækker Jamaica rom med fedme og finesse', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Nicaragua 1999, 18 y.o.', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-nicaragua-1999-18-y-o-2/', 799, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Bristol-Spirits-Nicaragua-1999-18-y.o..jpg', 'Bristol Classic Spirits. Rom-legenden John Barrett står bag Bristol Spirits, som er klassisk rom. Hver flaske er dateret med et vintage år. Det vil sige, at hvis der står 1990, så er alt indholdet destilleret i 1990. Med Bristol Spirits Nicaragua 1999 er en gammel kending tilbage, men bemærk at denne Nicaragua rom er destilleret i 1999 og tappet i 2017 og ikke destilleret i 2002 og tappet i 2015 som den tidligere Nicaragua rom fra Bristol Spirits. Smagsnoter: Denne Nicaragua rom er lys i farven og har en dejlig duft af søde frugter og eg. Smagen er let og rund med strejf af banan og eg, der leder op til en afbalanceret finish.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Port Mourant 1990-2022, 46,7%', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-port-mourant-1990-2022-467/', 3499.95, TRUE, NULL, 46.7, 'https://www.kokkensvinhus.dk/wp-content/uploads/2022/06/bristolclassicrumportmourant19902022-31.jpg', 'Bristol Classic Rum - Port Mourant 1990 - 2022 Endelig en ny spændende aftapnning fra John Barrett. Denne gang fra Diamond Distillery, Guyana Flot gylden farve med røde nuancer, fra lagringen i portvinsfade. Duften har klassisk Port Morant kompleksitet, med strejf af anis og frugt. Smagen er lang og med dybde, med noter af læder, tørrede frugter og anis, som fører til en lang og dyb finish. Se vores udvalg af Port Morant. &nbsp;', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bristol Spirits Reserve Rum of Belize 2005', 'https://www.kokkensvinhus.dk/shop/bristol-spirits-reserve-rum-of-belize-2005-2/', 899, TRUE, NULL, 46, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/bristol-belize.jpg', 'Bristol Spirits Classic. Denne Reserve Rum af Belize er en kolonne Still Rum, som destilleres i 2005 og afsendes af Travellers Liquor. I 2016 bliver den aftappet i Storbritannien af Bristol Spirits. Den har en god og behagelig finish med længde og stil. Vol. 46% Alder 11 År.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Alfred''s Trail Edt. 6.12 Belize Rum', 'https://www.kokkensvinhus.dk/shop/alfreds-trail-edt-6-12-belize-rum-2/', 795, TRUE, NULL, NULL, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/alfreds-trail-belize-rum.jpg', 'Produktionen er begrænset til kun 1.000 flasker, alle aftappet i hånden og afmærket med fad- og flaskenummer.', '2026-11-08 11:00:00+01');
