INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Blackadder RAW CASK TRINIDAD RUM 2010 11YO 66.4%', 'https://www.kokkensvinhus.dk/shop/blackadder-raw-cask-trinidad-rum-2010-11yo-66-4/', 1199, TRUE, NULL, 66.4, 'https://www.kokkensvinhus.dk/wp-content/uploads/2024/07/Trinidad11yoBLA.jpg', 'I sin fulde glans og styrke, fremstår denne rom med en alkoholprocent på 66,4%, der virkelig belyser dens dybe karaktær og unikke smagskomposition. Under alle omstændigheder er Blackadder Rawcask Trinidad 2010 en naturlig rom, der stolt præsenterer sin rige, ufiltrerede essens', '2026-11-08 11:00:00+01');
