INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Companero Gran Reserva 40% Jamaica/ Trinidad', 'https://www.kokkensvinhus.dk/shop/companero-gran-reserva-40-jamaica-trinidad-2/', 349.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/companero-rom.jpg', 'Ved at kombinere den kraftfulde duft af Jamaica rom med den bløde og elegante smag fra Trinidad rommen, har Compañero Gran Reserva en perfekt afbalanceret smag med en dejlig finish.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Companero Ron Elixir Orange 40%', 'https://www.kokkensvinhus.dk/shop/companero-ron-elixir-orange-40/', 349.95, TRUE, NULL, 40, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/companero-elixir-orange-trinidad-1296739.jpg', 'Sød, fyldig og elegante aromaer af appelsiner og kokos. Elixir Orange er en ”venlig” romlikør, der egner sig rigtig godt til dem med en sød tand.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Companero Ron Panama 54% Extra Anejo', 'https://www.kokkensvinhus.dk/shop/companero-ron-panama-54-extra-anejo-2/', 399.95, TRUE, NULL, 54, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/companero-ron-panama-54.jpg', 'Compa&ntilde;ero Ron Panama 54% er den tredje rom i Compa&ntilde;ero serien. De 54% bliver flot gemt v&aelig;k i sk&oslash;nne toner af chokolade, der giver varme og dybde til denne Panama rom. Compa&ntilde;ero er det spanske ord for kammerat, og det danner rammen om denne serie af produkter fra danske 1423, hvor smag, kompleksitet og finish er ultimative n&oslash;gleord.De to f&oslash;rste produkter i serien, Gran Reserva og Elixir Orange, er begge fra Caribien, mens den tredje rom her s&aring; er fra Panama.I n&aelig;sen f&aring;r man tung m&oslash;rk chokolade, varm fl&oslash;de og strejf af citrus. Smag: N&aelig;sten som mini muh chokolade og kakao-agtig. Compa&ntilde;ero Ron Panama Extra A&ntilde;ejo er fadpr&aelig;get og med en lille bitte smule orange, men chokoladen overd&oslash;ver det meste.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Blackadder Four Square Rum 2004, 64,1% 12 yo Barbados', 'https://www.kokkensvinhus.dk/shop/blackadder-four-square-rum-2004-641-12-yo-barbados-2/', 899, TRUE, NULL, 64.1, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/blackadder-four-square.jpg', 'Barbados rom for fuld skrue! Tappet i Blackadder''s RawCask serie, på fuld alkoholstyre 64,1%.', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Royal Cane Barbados 2005, 17YO 58 %', 'https://www.kokkensvinhus.dk/shop/royal-cane-barbados-2005-17yo-58/', 1499, FALSE, NULL, 58, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/06/Royal-Cane-Barbados-2005-002.jpg', 'Royal Cane Barbados. Royal Cane''s Barbados rom er destilleret på det berømte Four Square destilleri på Øen. Rommen er destilleret i 2005 og er en blanding af rom fra Pot stills og Kolonne kedler, efter den er blended, kommer rommen på fade af amerikansk hvid eg og så lager den på Barbados, under tropiske forhold i 12 år, til 2017 hvor rommen af skippes til Liverpool, hvor den lagre yderligere 5 år, i de historiske lagerhaller i byen. Facts om Rommen! Four Square Destilleri Destillations År: 2005 Aftapnings År: 2022 Alder: 17 år Fad type: Amerikansk Hvid Eg Basis Materiale: Melasse Destillations Apparat: Pot Still &amp; Kolonne Kedel. Styrke: 58%', '2026-11-08 11:00:00+01');
INSERT INTO stg_kokkensvinhus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cane Island Venezuela Single Estate Rum 8 y.o. 43%', 'https://www.kokkensvinhus.dk/shop/cane-island-venezuela-single-estate-rum-8-y-o-43/', 399, FALSE, NULL, 43, 'https://www.kokkensvinhus.dk/wp-content/uploads/2021/08/Cane-Island-Venezuela-Single-Estate-Rum-8-y.o.-43.jpg', '8 år gammel Single Estate Rum', '2026-11-08 11:00:00+01');
